package dev.pocket.agent;

import android.app.*;
import android.content.*;
import android.graphics.Typeface;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;

/** Native messaging inbox for persistent local bots. Legacy workspace tools remain accessible. */
public class BotsActivity extends Activity {
    private final Handler main=new Handler(Looper.getMainLooper());
    private final ExecutorService io=Executors.newFixedThreadPool(2);
    private AgentApi api;private JSONObject state=new JSONObject(),detail;private String selected="",draft="",signature="";
    private LinearLayout page,body,thread;private EditText composer;private ScrollView chatScroll;private boolean visible,polling,follow=true;
    private final Runnable poll=() -> refresh(false);
    interface Result {void done(Object value)throws Exception;}
    int dp(int n){return AgentStyle.dp(this,n);}
    JSONObject json(Object...pairs){JSONObject value=new JSONObject();try{for(int i=0;i<pairs.length;i+=2)value.put((String)pairs[i],pairs[i+1]);}catch(Exception e){throw new IllegalArgumentException(e);}return value;}
    LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
    LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    TextView text(String value,int size){TextView v=AgentStyle.text(this,value,size);v.setPadding(dp(8),dp(6),dp(8),dp(6));return v;}
    TextView muted(String value,int size){TextView v=text(value,size);v.setTextColor(AgentStyle.MUTED);return v;}
    Button button(LinearLayout parent,String title,Runnable action,boolean primary){Button v=new Button(this);v.setText(title);AgentStyle.button(v,primary);parent.addView(v);v.setOnClickListener(w -> action.run());return v;}
    EditText field(LinearLayout parent,String label,String value,boolean secret){parent.addView(text(label,12));EditText v=new EditText(this);AgentStyle.input(v);v.setSingleLine(true);if(secret)v.setInputType(129);v.setText(value);parent.addView(v);return v;}
    void request(String method,String path,JSONObject data,Result done){if(api==null)return;AgentApi connection=api;io.execute(() -> {try{Object value=connection.request(method,path,data);main.post(() -> {if(!isDestroyed())try{done.done(value);}catch(Exception e){error(e);}});}catch(Exception e){main.post(() -> {if(!isDestroyed())error(e);});}});}
    void error(Exception e){new AlertDialog.Builder(this).setTitle("Pocket Agent").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);selected=getIntent().getStringExtra("botId");if(selected==null)selected="";if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},1);}
    @Override protected void onResume(){super.onResume();visible=true;startForegroundService(new Intent(this,RuntimeService.class));connect();}
    private void connect(){if(!visible)return;if(!RuntimeService.ready){LinearLayout wait=column();wait.setPadding(dp(24),dp(40),dp(24),dp(24));wait.setBackgroundColor(AgentStyle.BACK);wait.addView(text("Pocket Agent",24));wait.addView(muted(RuntimeService.status,14));button(wait,"Retry / runtime log",() -> startActivity(new Intent(this,MainActivity.class)),false);setContentView(wait);main.postDelayed(this::connect,700);return;}
        try{api=new AgentApi((String)new JSONTokener(Io.text(new File(getFilesDir(),"state/token.json"))).nextValue());refresh(true);}catch(Exception e){error(e);}}
    @Override protected void onPause(){visible=false;main.removeCallbacks(poll);super.onPause();}
    @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
    private void refresh(boolean rebuild){
        if(!visible||api==null||polling)return;polling=true;String id=selected;
        io.execute(() -> {try{JSONObject next=api.get("/state"),nextDetail=id.isEmpty()?null:api.get("/bots/"+id);main.post(() -> {polling=false;if(!visible||!id.equals(selected))return;state=next;detail=nextDetail;String changed=(id.isEmpty()?next.optJSONArray("bots"):nextDetail).toString()+next.optBoolean("botEngineEnabled");
            if(rebuild||body==null){shell();signature="";}if(!signature.equals(changed)){signature=changed;if(selected.isEmpty())inbox();else renderThread();}main.postDelayed(poll,1000);});}
            catch(Exception e){main.post(() -> {polling=false;if(visible){main.postDelayed(poll,2000);if(rebuild)error(e);}});}});
    }
    private void open(String id){if(composer!=null){draft=composer.getText().toString();composer=null;}selected=id;draft="";detail=null;signature="";main.removeCallbacks(poll);refresh(true);}
    private void shell(){
        page=column();page.setBackgroundColor(AgentStyle.BACK);page.setPadding(dp(12),dp(8),dp(12),dp(8));LinearLayout header=row();
        AgentIcon back=new AgentIcon(this,selected.isEmpty()?"menu":"back",selected.isEmpty()?"Workspace menu":"Back to bots",() -> {if(selected.isEmpty())menu();else open("");});header.addView(back,new LinearLayout.LayoutParams(dp(44),dp(44)));
        LinearLayout identity=column();TextView title=text(selected.isEmpty()?"Pocket Agent":detail.optJSONObject("bot").optString("name"),20);title.setTypeface(AgentStyle.font(this),Typeface.BOLD);identity.addView(title);identity.addView(muted(selected.isEmpty()?"Your local bots":detail.optJSONObject("bot").optString("kind")+" bot · on this phone",11));header.addView(identity,new LinearLayout.LayoutParams(0,-2,1));
        header.addView(new AgentIcon(this,selected.isEmpty()?"plus":"settings",selected.isEmpty()?"Create bot":"Bot settings",() -> editBot(selected.isEmpty()?null:detail.optJSONObject("bot"))),new LinearLayout.LayoutParams(dp(44),dp(44)));page.addView(header);
        body=column();page.addView(body,new LinearLayout.LayoutParams(-1,0,1));composer=null;thread=null;
        if(!selected.isEmpty()){
            chatScroll=new ScrollView(this);thread=column();chatScroll.addView(thread);body.addView(chatScroll,new LinearLayout.LayoutParams(-1,0,1));chatScroll.setOnScrollChangeListener((v,x,y,ox,oy) -> follow=y+chatScroll.getHeight()>=thread.getHeight()-dp(60));
            LinearLayout input=row();input.setPadding(dp(4),dp(4),dp(4),dp(4));input.setBackground(AgentStyle.surface(this,AgentStyle.PANEL,28,true));composer=new EditText(this);AgentStyle.input(composer);composer.setBackgroundColor(android.graphics.Color.TRANSPARENT);composer.setHint("Message "+detail.optJSONObject("bot").optString("name")+"…");composer.setMaxLines(5);composer.setText(draft);input.addView(composer,new LinearLayout.LayoutParams(0,-2,1));AgentIcon send=new AgentIcon(this,"send","Send to bot",this::send);send.setBackground(AgentStyle.surface(this,AgentStyle.BLUE,28,false));input.addView(send,new LinearLayout.LayoutParams(dp(44),dp(44)));page.addView(input);
        }
        setContentView(page);
    }
    private void menu(){new AlertDialog.Builder(this).setTitle("Pocket Agent").setItems(new String[]{"Bots","MCP connections","Model / BYOK settings","Coding workspace","Phone tasks"},(d,n) -> {if(n==0)open("");if(n==1)connections();if(n>=2){getSharedPreferences("native-ui",MODE_PRIVATE).edit().putString("mode",n==4?"Mobile Use":"Coding").apply();startActivity(new Intent(this,MainActivity.class).putExtra("openSettings",n==2));}}).show();}
    private void inbox(){
        body.removeAllViews();LinearLayout engine=row();Switch toggle=new Switch(this);toggle.setText("Keep bots running");toggle.setTextColor(AgentStyle.TEXT);toggle.setChecked(state.optBoolean("botEngineEnabled"));engine.addView(toggle,new LinearLayout.LayoutParams(0,dp(48),1));body.addView(engine);
        toggle.setOnCheckedChangeListener((v,on) -> setEngine(on,() -> refresh(true)));body.addView(muted("Tasks continue outside the app. Android may stop work after force-stop, shutdown, or battery restrictions.",11));
        ScrollView scroll=new ScrollView(this);LinearLayout list=column();scroll.addView(list);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));JSONArray bots=state.optJSONArray("bots");
        if(bots==null||bots.length()==0){list.addView(text("Meet your local bots",23));list.addView(muted("Create teammates with different jobs. Chat, queue tasks, and set proactive routines.",14));button(list,"Create my first bot",() -> editBot(null),true);return;}
        for(int i=0;i<bots.length();i++){JSONObject bot=bots.optJSONObject(i);String id=bot.optString("id");LinearLayout item=row();item.setPadding(dp(6),dp(12),dp(6),dp(12));
            TextView avatar=text(bot.optString("name","?").substring(0,1).toUpperCase(java.util.Locale.ROOT),20);avatar.setGravity(Gravity.CENTER);avatar.setTypeface(AgentStyle.font(this),Typeface.BOLD);int color=bot.optString("kind").equals("coding")?0xff233b70:bot.optString("kind").equals("phone")?0xff4a306a:0xff1d5447;avatar.setBackground(AgentStyle.surface(this,color,24,false));item.addView(avatar,new LinearLayout.LayoutParams(dp(48),dp(48)));
            LinearLayout copy=column();LinearLayout title=row();TextView name=text(bot.optString("name"),16);name.setTypeface(AgentStyle.font(this),Typeface.BOLD);title.addView(name,new LinearLayout.LayoutParams(0,-2,1));title.addView(muted(bot.optJSONObject("active")!=null?bot.optJSONObject("active").optString("status"):bot.optBoolean("enabled")?"Ready":"Paused",10));copy.addView(title);JSONObject last=bot.optJSONObject("lastMessage");TextView preview=muted(last==null?bot.optString("role"):last.optString("text"),12);preview.setMaxLines(2);preview.setEllipsize(android.text.TextUtils.TruncateAt.END);copy.addView(preview);copy.addView(muted(bot.optString("kind")+" · "+bot.optInt("queued")+" queued"+(bot.optInt("intervalMinutes")>0?" · every "+bot.optInt("intervalMinutes")+" min":""),10));item.addView(copy,new LinearLayout.LayoutParams(0,-2,1));list.addView(item);item.setOnClickListener(v -> open(id));View line=new View(this);line.setBackgroundColor(AgentStyle.BORDER);list.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}
    }
    private void setEngine(boolean enabled,Runnable done){request("PUT","/bots/engine",json("enabled",enabled),v -> {getSharedPreferences("bot-runtime",MODE_PRIVATE).edit().putBoolean("enabled",enabled).apply();startForegroundService(new Intent(this,RuntimeService.class).putExtra("botsEnabled",enabled));done.run();});}
    private void send(){String value=composer.getText().toString().trim();if(value.isEmpty())return;String id=selected;setEngine(true,() -> request("POST","/bots/"+id+"/messages",json("text",value),v -> {composer.setText("");draft="";request("POST","/bots/"+id+"/resume",json(),r -> refresh(false));}));}
    private void bubble(String value,boolean user){LinearLayout align=column();align.setGravity(user?Gravity.RIGHT:Gravity.LEFT);TextView message=text(value,14);message.setTextIsSelectable(true);message.setPadding(dp(14),dp(12),dp(14),dp(12));message.setMaxWidth(getResources().getDisplayMetrics().widthPixels-dp(64));message.setBackground(AgentStyle.surface(this,user?AgentStyle.BLUE:AgentStyle.PANEL,20,!user));align.addView(message,new LinearLayout.LayoutParams(-2,-2));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(7));thread.addView(align,p);}
    private void renderThread(){
        if(thread==null||detail==null)return;int old=chatScroll.getScrollY();boolean scroll=follow;thread.removeAllViews();JSONObject bot=detail.optJSONObject("bot");JSONArray messages=detail.optJSONArray("messages");
        for(int i=0;i<messages.length();i++){JSONObject message=messages.optJSONObject(i);if(message.optString("role").equals("system"))thread.addView(muted(message.optString("text"),11));else bubble(message.optString("text"),message.optString("role").equals("user"));}
        JSONObject session=detail.optJSONObject("session");if(session!=null){JSONObject streaming=session.optJSONObject("streaming");if(streaming!=null){StringBuilder out=new StringBuilder();JSONArray parts=streaming.optJSONArray("content");if(parts!=null)for(int i=0;i<parts.length();i++){JSONObject part=parts.optJSONObject(i);if(part!=null&&part.optString("type").equals("text"))out.append(part.optString("text"));}if(out.length()>0)bubble(out.toString(),false);}
            JSONArray approvals=session.optJSONArray("approvals");if(approvals!=null)for(int i=0;i<approvals.length();i++){JSONObject approval=approvals.optJSONObject(i);thread.addView(text("Allow "+approval.optString("tool")+"?\n"+approval.opt("args"),12));LinearLayout actions=row();thread.addView(actions);for(boolean allow:new boolean[]{true,false})button(actions,allow?"Allow":"Deny",() -> request("POST","/approvals/"+approval.optString("id"),json("allow",allow),v -> refresh(false)),allow);}}
        JSONObject phone=detail.optJSONObject("mobileTask");if(phone!=null){if(!phone.optString("output").isEmpty())bubble(phone.optString("output"),false);JSONObject question=phone.optJSONObject("question");if(question!=null){bubble(question.optString("text"),false);button(thread,"Reply in floating island",() -> {startForegroundService(new Intent(this,MobileOverlayService.class).putExtra("taskId",phone.optString("id")).putExtra("expand",true));moveTaskToBack(true);},true);}}
        JSONArray jobs=detail.optJSONArray("jobs");boolean busy=false;for(int i=Math.max(0,jobs.length()-8);i<jobs.length();i++){JSONObject job=jobs.optJSONObject(i);String status=job.optString("status");if(Arrays.asList("completed","cancelled").contains(status))continue;busy|=Arrays.asList("running","arming","waiting").contains(status);LinearLayout card=column();card.setPadding(dp(8),dp(8),dp(8),dp(8));AgentStyle.card(card);TextView summary=text(status.toUpperCase(java.util.Locale.ROOT)+" · "+job.optString("text"),11);summary.setMaxLines(3);card.addView(summary);if(!job.optString("error").isEmpty())card.addView(muted(job.optString("error"),12));if(!status.equals("failed"))button(card,"Cancel task",() -> request("POST","/bots/"+selected+"/jobs/"+job.optString("id")+"/cancel",json(),v -> refresh(false)),false);thread.addView(card);}
        if(busy){LinearLayout thinking=row();ThinkingOrbView orb=new ThinkingOrbView(this);orb.state("running");thinking.addView(orb,new LinearLayout.LayoutParams(dp(30),dp(30)));thinking.addView(muted("Working · you can queue another task",12));thread.addView(thinking);}
        LinearLayout controls=row();thread.addView(controls);button(controls,bot.optBoolean("enabled")?"Pause bot":"Resume bot",() -> {MobileAccess.authorize(false);request("POST","/bots/"+selected+(bot.optBoolean("enabled")?"/pause":"/resume"),json(),v -> refresh(false));},false);if(bot.optString("kind").equals("coding"))button(controls,"Open workspace",() -> {getSharedPreferences("native-ui",MODE_PRIVATE).edit().putString("mode","Coding").putString("project",bot.optString("projectId")).putString("session",bot.optString("sessionId")).apply();startActivity(new Intent(this,MainActivity.class));},false);
        thread.addView(muted("Runs today: "+bot.optInt("runs")+" / "+bot.optInt("dailyLimit")+(bot.optInt("intervalMinutes")>0?" · Routine every "+bot.optInt("intervalMinutes")+" min":""),10));chatScroll.post(() -> {if(scroll)chatScroll.fullScroll(View.FOCUS_DOWN);else chatScroll.scrollTo(0,old);});
    }
    private void editBot(JSONObject bot){
        boolean creating=bot==null;LinearLayout form=column();form.setPadding(dp(16),dp(8),dp(16),dp(16));ScrollView scroll=new ScrollView(this);scroll.addView(form);
        EditText name=field(form,"Name",creating?"":bot.optString("name"),false);Spinner kind=new Spinner(this);kind.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Coding bot","Phone helper","Browser bot"}));form.addView(text("What can this bot do?",12));form.addView(kind);if(!creating){kind.setSelection(bot.optString("kind").equals("coding")?0:bot.optString("kind").equals("phone")?1:2);kind.setEnabled(false);}
        EditText role=field(form,"Role & instructions",creating?"":bot.optString("role"),false);role.setSingleLine(false);role.setMinLines(3);role.setGravity(Gravity.TOP);role.setHint("e.g. Maintain my app and check tests, or research topics in Chrome");
        CheckBox shell=new CheckBox(this);shell.setText("Allow shell commands without asking");shell.setChecked(!creating&&bot.optBoolean("allowShell"));form.addView(shell);
        form.addView(muted("Phone/browser bots read and operate the visible screen via Artemis. Android permissions and an unlocked device are required.",11));
        if(creating){button(form,"Enable phone accessibility",() -> startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)),false);button(form,"Allow floating island",() -> startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,android.net.Uri.parse("package:"+getPackageName()))),false);}
        EditText interval=field(form,"Proactive interval in minutes · 0 = off",creating?"0":bot.optString("intervalMinutes"),false),routine=field(form,"Routine task",creating?"":bot.optString("heartbeat"),false),limit=field(form,"Maximum runs per day",creating?"24":bot.optString("dailyLimit"),false);interval.setInputType(2);limit.setInputType(2);routine.setSingleLine(false);routine.setMinLines(2);
        form.addView(text("MCP connections",14));JSONArray all=state.optJSONArray("connectors");Map<String,CheckBox> selectedConnections=new LinkedHashMap<>();if(all!=null)for(int i=0;i<all.length();i++){JSONObject connection=all.optJSONObject(i);CheckBox check=new CheckBox(this);check.setText(connection.optString("name"));if(!creating&&bot.optJSONArray("connectors")!=null)check.setChecked(bot.optJSONArray("connectors").toString().contains(connection.optString("id")));form.addView(check);selectedConnections.put(connection.optString("id"),check);}button(form,"Manage MCP connections",this::connections,false);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(creating?"Create a bot":"Bot profile").setView(scroll).setPositiveButton(creating?"Create bot":"Save",null).setNegativeButton("Cancel",null).create();
        dialog.setOnShowListener(v -> dialog.getButton(-1).setOnClickListener(w -> {try{JSONArray ids=new JSONArray();for(Map.Entry<String,CheckBox> entry:selectedConnections.entrySet())if(entry.getValue().isChecked())ids.put(entry.getKey());JSONObject data=json("name",name.getText().toString(),"role",role.getText().toString(),"kind",new String[]{"coding","phone","browser"}[kind.getSelectedItemPosition()],"allowShell",shell.isChecked(),"intervalMinutes",Integer.parseInt(interval.getText().toString()),"heartbeat",routine.getText().toString(),"dailyLimit",Integer.parseInt(limit.getText().toString()),"connectors",ids);
            request(creating?"POST":"PUT",creating?"/bots":"/bots/"+bot.optString("id"),data,result -> {dialog.dismiss();open(((JSONObject)result).optString("id"));});}catch(Exception e){error(e);}}));dialog.show();
    }
    private void connections(){request("GET","/connectors",null,value -> {JSONArray list=(JSONArray)value;LinearLayout form=column();form.setPadding(dp(12),0,dp(12),dp(12));button(form,"Add MCP connection",() -> connectionForm(null),true);for(int i=0;i<list.length();i++){JSONObject c=list.optJSONObject(i);button(form,c.optString("name")+" · "+c.optString("transport"),() -> new AlertDialog.Builder(this).setTitle(c.optString("name")).setItems(new String[]{"Test connection","Edit","Remove"},(d,n) -> {if(n==0)request("POST","/connectors/"+c.optString("id")+"/test",json(),r -> new AlertDialog.Builder(this).setTitle("Connected").setMessage(((JSONObject)r).optJSONArray("tools").length()+" tools available").setPositiveButton("OK",null).show());if(n==1)connectionForm(c);if(n==2)request("DELETE","/connectors/"+c.optString("id"),null,r -> {refresh(false);});}).show(),false);}ScrollView scroll=new ScrollView(this);scroll.addView(form);new AlertDialog.Builder(this).setTitle("MCP connections").setView(scroll).setPositiveButton("Close",null).show();});}
    private void connectionForm(JSONObject previous){LinearLayout form=column();form.setPadding(dp(16),0,dp(16),dp(16));EditText name=field(form,"Name",previous==null?"":previous.optString("name"),false);Spinner transport=new Spinner(this);transport.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"HTTP endpoint","Local stdio command"}));form.addView(transport);if(previous!=null)transport.setSelection(previous.optString("transport").equals("stdio")?1:0);EditText url=field(form,"HTTP URL",previous==null?"":previous.optString("url"),false),token=field(form,"Bearer token · blank keeps saved token","",true),command=field(form,"Local executable",previous==null?"npx":previous.optString("command"),false),args=field(form,"Arguments · JSON array",previous==null?"[]":previous.optJSONArray("args").toString(),false);ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("MCP connection").setView(scroll).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v -> dialog.getButton(-1).setOnClickListener(w -> {try{JSONObject data=json("name",name.getText().toString(),"transport",transport.getSelectedItemPosition()==0?"http":"stdio","url",url.getText().toString(),"token",token.getText().toString(),"command",command.getText().toString(),"args",new JSONArray(args.getText().toString()));if(previous!=null)data.put("id",previous.optString("id"));request("POST","/connectors",data,r -> {dialog.dismiss();refresh(false);});}catch(Exception e){error(e);}}));dialog.show();}
    @Override public void onBackPressed(){if(!selected.isEmpty())open("");else super.onBackPressed();}
}
